1	package status
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/charmbracelet/lipgloss"
8	
9		"github.com/anthnel/devdesk/internal/status"
10		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
11		"github.com/anthnel/devdesk/internal/ui/help"
12		"github.com/anthnel/devdesk/internal/ui/shortcut"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	
15		"github.com/anthnel/devdesk/internal/ui/keymap"
16	)
17	
18	func (m Model) InEditMode() bool {
19		return m.componentForm != nil || m.filterBar.InEditMode()
20	}
21	
22	// FilterBarVisible returns true when the filter bar is visible (implements app.FilterBarView).
23	func (m Model) FilterBarVisible() bool {
24		return m.filterBar.IsVisible() && m.componentForm == nil && m.confirmModal == nil && m.error == "" && len(m.components) > 0
25	}
26	
27	func (m Model) GetShortcuts() shortcut.Shortcuts {
28		// component edit/add view
29		if m.componentForm != nil {
30			return []shortcut.Shortcut{
31				{Key: "esc", Description: "Cancel"},
32				{Key: "enter", Description: "Submit"},
33			}
34		}
35	
36		// main status view
37		return []shortcut.Shortcut{
38			{Key: keymap.New, Description: "New monitor"},
39			{Key: keymap.Edit, Description: "Edit monitor"},
40			{Key: keymap.Delete, Description: "Delete monitor"},
41			{Key: "ctrl+r", Description: "Refresh"},
42			{Key: "tab", Description: "Switch tab"},
43			{Key: ".", Description: "Sort"},
44			{Key: "/", Description: "Search"},
45			{Key: "ctrl+p", Description: "Command mode"},
46			{Key: "?", Description: "Help"},
47		}
48	}
49	
50	func (m Model) GetTitle() string {
51		base := theme.IconService + " Status Monitor"
52		if m.componentForm != nil {
53			return base + " " + theme.IconChevronRight + " " + m.componentForm.GetTitle()
54		}
55		return base
56	}
57	
58	func (m Model) GetIcon() string {
59		return ""
60	}
61	
62	// GetHeaderInfo returns the key-value info for the header. The component
63	// count lives here rather than in the body (Rule 139): an empty table stays a
64	// table, header and no rows.
65	func (m Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
66		return []shortcut.HeaderInfo{
67			{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
68			{Key: "Refresh", Value: fmt.Sprintf("%ds", int(m.refreshInterval.Seconds())), Style: theme.HeaderValueStyle},
69			{Key: "Components", Value: fmt.Sprintf("%d", len(m.components)), Style: theme.HeaderValueStyle},
70		}
71	}
72	
73	// View renders the view
74	func (m Model) View() string {
75		// Form mode - overlay
76		if m.componentForm != nil {
77			return m.componentForm.View()
78		}
79	
80		// Confirmation mode - overlay
81		if m.confirmModal != nil {
82			return lipgloss.Place(
83				m.width,
84				m.height,
85				lipgloss.Center,
86				lipgloss.Center,
87				m.confirmModal.View(),
88				lipgloss.WithWhitespaceBackground(theme.ColorBackground),
89			)
90		}
91	
92		// Content - DYNAMIC HEIGHT that fills exactly the available space
93		if m.error != "" {
94			return m.renderError()
95		}
96		return m.renderTable()
97	}
98	
99	func (m Model) renderError() string {
100		msg := fmt.Sprintf("✗ Error: %s", m.error)
101		return lipgloss.NewStyle().
102			Background(theme.ColorBackground).
103			Padding(2, 4).
104			Foreground(theme.ColorError).
105			Render(msg)
106	}
107	
108	// status is what the view derives on every frame. The check has no timer: it
109	// lasts exactly as long as it lasts.
110	func (m Model) status() sharedcomponents.Status {
111		if m.checking {
112			return sharedcomponents.Status{Text: "Checking components...", Spinner: true}
113		}
114		return sharedcomponents.Status{}
115	}
116	
117	// renderTabs renders the tab bar for monitors/certificates
118	func (m Model) renderTabs() string {
119		monitorCount := len(m.monitorTable.Visible())
120		sslCount := len(m.sslTable.Visible())
121	
122		return theme.RenderTabs([]theme.TabItem{
123			{Label: fmt.Sprintf("Service Monitors (%d)", monitorCount)},
124			{Label: fmt.Sprintf("SSL Certificates (%d)", sslCount)},
125		}, m.activeTab)
126	}
127	
128	func (m Model) renderTable() string {
129		if m.activeTab == TabMonitors {
130			return m.monitorTable.View()
131		}
132		return m.sslTable.View()
133	}
134	
135	// GetFooterHeight returns the footer height for this view (Rule 124).
136	func (m Model) GetFooterHeight() int {
137		if m.componentForm == nil && m.confirmModal == nil && m.error == "" && len(m.components) > 0 {
138			return 3 + m.filterBar.ExtraHeight() // filter bar (when visible) + tab bar + empty line + info line
139		}
140		return 2 // empty line + info line
141	}
142	
143	// RenderFooter returns the footer content rendered below the viewport (Rule 124).
144	func (m Model) RenderFooter(width int) string {
145		if m.componentForm == nil && m.confirmModal == nil && m.error == "" && len(m.components) > 0 {
146			var parts []string
147			if m.filterBar.IsVisible() {
148				parts = append(parts, m.filterBar.View())
149			}
150			parts = append(parts,
151				theme.PadWithBg(theme.Bg(" ")+m.renderTabs(), width),
152				theme.EmptyLineBg(width),
153				m.footer.View(width, m.status()),
154			)
155			return strings.Join(parts, "\n")
156		}
157		return theme.EmptyLineBg(width) + "\n" + m.footer.View(width, m.status())
158	}
159	
160	// updateTable refills both tables from the last check.
161	//
162	// The text query stays here rather than moving into either table's own filter
163	// bar: one bar drives two tables, so that the header counts agree with each
164	// other whichever tab is showing. The component models a bar per table, which
165	// is the right default and the wrong shape for this one view.
166	func (m *Model) updateTable() {
167		query := strings.ToLower(strings.TrimSpace(m.filterBar.SearchQuery()))
168	
169		var monitors, ssls []status.ComponentStatus
170		for _, comp := range m.components {
171			if !matchesQuery(comp, query) {
172				continue
173			}
174			if comp.Type == "ssl" {
175				ssls = append(ssls, comp)
176			} else {
177				monitors = append(monitors, comp)
178			}
179		}
180	
181		m.monitorTable.SetItems(monitors)
182		m.sslTable.SetItems(ssls)
183		m.applyTabFocus()
184	}
185	
186	// GetHelpContent returns the help content for the Status view
187	func (m Model) GetHelpContent() help.Content {
188		return help.Content{
189			Title:       "Status Monitor",
190			Description: "This view monitors the status of your services in real time. Checks are performed automatically at regular intervals. Two tabs display service monitors (HTTP, ICMP, DNS) and SSL certificates respectively.",
191			KeyBindings: []help.KeyBinding{
192				{Key: keymap.New, Description: "Add a new monitor"},
193				{Key: keymap.Edit, Description: "Edit the selected monitor"},
194				{Key: keymap.Delete, Description: "Delete the selected monitor (with confirmation)"},
195				{Key: "ctrl+r", Description: "Force an immediate refresh"},
196				{Key: "tab/shift+tab", Description: "Switch between Service Monitors and SSL Certificates tabs"},
197				{Key: "↑/k", Description: "Move selection up"},
198				{Key: "↓/j", Description: "Move selection down"},
199				{Key: ".", Description: "Cycle sort column and direction (Name, Target, Type, Response). Each column cycles ascending then descending before moving to the next. The active sort is shown with ▲ or ▼ in the column header."},
200				{Key: "/", Description: "Filter the active table by name, target or type"},
201				{Key: "ctrl+p", Description: "Open command mode"},
202				{Key: "?", Description: "Show this help"},
203			},
204			Sections: []help.Section{
205				{
206					Title: "Monitor Types",
207					Body:  "HTTP/HTTPS: checks URL availability and measures response time.\nICMP (Ping): checks network connectivity to a host.\nDNS: checks domain name resolution.\nSSL: checks the validity and expiration of an SSL/TLS certificate.",
208				},
209				{
210					Title: "Configuration",
211					Body:  "Monitors are saved in the active context configuration file (~/.devdesk/contexts/<context>/config.yaml). The refresh interval and auto-refresh are settings, edited in the configuration view (:config, Status tab) — not here.",
212				},
213			},
214		}
215	}
216	
217	// formatSSLStatus names a certificate's state, and it does not go through
218	// StatusType.
219	//
220	// It used to, and that is what earned the Health box D64: SSLChecker
221	// renders `ERROR` for an expired certificate just as for one expiring in six
222	// days, so the icon was the same for both. The `Days Left` column beside it
223	// separated what this one glued together — but it required reading two
224	// cells for a fact that fits in one.
225	//
226	// The text stays plain: the color is the column's `Style` (Rule 122).
227	func formatSSLStatus(comp status.ComponentStatus) string {
228		return theme.CertStateIcon(string(status.CertStateOf(comp)))
229	}
230	
231	// matchesQuery reports whether a component survives the text filter. Name,
232	// target and type, which is what the two loops this replaced matched between
233	// them — the SSL one left type out, and a `type:` query narrowing one table and
